var c = $feature.COMPARE_CLASS; var ids = DefaultValue($feature.COUNTY_IDS, '');
var words = Dictionary('MATCH', 'matches one county footprint', 'RESHAPED', 'the county outline is offset or drawn differently', 'LIDAR_JOINS', 'one building where the county has several outlines', 'LIDAR_SPLITS', 'part of what the county draws as one outline', 'TANGLE', 'overlaps several county outlines in a mixed way', 'LIDAR_ONLY', 'not in the county footprints', 'COUNTY_ONLY', 'county footprint kept: its roof is hidden from the lidar by trees');
var t = IIf(HasKey(words, c), words[c], 'not compared');
